tool_use_result.content:
/* ===== Reset & Base ===== */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --primary: #02838D;
  --primary-light: #06A4B0;
  --primary-dark: #016A73;
  --primary-bg: #E8F6F7;
  --charcoal: #231F20;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --coral: #E8915A;
  --coral-dark: #D4763E;
  --green-light: #E8F5E9;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: var(--font);
  color: var(--charcoal);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
  transition: color 0.2s;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

ul { list-style: none; }

img { max-width: 100%; display: block; }

/* ===== Credibility Ticker ===== */
.credibility-ticker {
  background: var(--primary);
  color: var(--white);
  overflow: hidden;
  white-space: nowrap;
  padding: 10px 0;
  position: relative;
  z-index: 100;
}

.ticker-track {
  display: inline-flex;
  align-items: center;
  gap: 32px;
  animation: ticker-scroll 30s linear infinite;
}

.ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.ticker-icon {
  font-size: 16px;
  opacity: 0.9;
}

.ticker-divider {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(255,255,255,0.4);
  flex-shrink: 0;
}

@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ===== Header ===== */
.site-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  z-index: 90;
  box-shadow: var(--shadow-sm);
}

.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  height: 64px;
  gap: 32px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.logo-icon {
  font-size: 28px;
  color: var(--primary);
}

.logo-text {
  font-size: 22px;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: -0.02em;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.nav-item {
  position: relative;
}

.nav-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  border-radius: var(--radius-sm);
  transition: background 0.2s, color 0.2s;
}

.nav-link:hover {
  background: var(--gray-100);
  color: var(--primary);
}

.nav-arrow {
  font-size: 10px;
  transition: transform 0.2s;
}

.nav-item.active .nav-arrow {
  transform: rotate(180deg);
}

.nav-item.active .nav-link {
  background: var(--primary-bg);
  color: var(--primary);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--gray-200);
  padding: 24px 28px;
  min-width: 480px;
  opacity: 0;
  visibility: hidden;
  transform: translateX(-50%) translateY(8px);
  transition: opacity 0.2s, transform 0.2s, visibility 0.2s;
  z-index: 100;
}

.nav-item.active .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.mega-menu-inner {
  display: flex;
  gap: 32px;
}

.mega-col h4 {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--primary-bg);
}

.mega-col ul {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.mega-col a {
  font-size: 14px;
  color: var(--gray-700);
  padding: 6px 10px;
  border-radius: 6px;
  transition: background 0.15s, color 0.15s;
  display: block;
}

.mega-col a:hover {
  background: var(--primary-bg);
  color: var(--primary);
}

.mega-highlight {
  background: var(--primary-bg);
  padding: 16px 20px;
  border-radius: var(--radius-md);
  margin: -8px -12px;
  align-self: flex-start;
}

/* Header Actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.btn-subscribe {
  padding: 8px 20px;
  background: var(--primary);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}

.btn-subscribe:hover {
  background: var(--primary-dark);
}

.btn-signin {
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  color: var(--primary);
  border: 1.5px solid var(--primary);
  border-radius: var(--radius-sm);
  transition: background 0.2s, color 0.2s;
}

.btn-signin:hover {
  background: var(--primary);
  color: var(--white);
}

/* Mobile Menu Toggle */
.mobile-menu-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.mobile-menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--charcoal);
  border-radius: 2px;
  transition: transform 0.3s, opacity 0.3s;
}

/* ===== Section Common ===== */
.section-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.section-title {
  font-size: 28px;
  font-weight: 800;
  color: var(--charcoal);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28px;
}

.view-all {
  font-size: 14px;
  font-weight: 600;
  color: var(--primary);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: gap 0.2s;
}

.view-all:hover {
  gap: 8px;
}

.view-all::after {
  content: '\2192';
}

/* ===== Hero ===== */
.hero {
  background: linear-gradient(135deg, var(--primary-bg) 0%, #F0FBFC 50%, var(--white) 100%);
  padding: 48px 0;
}

.hero-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.hero-category {
  display: inline-block;
  padding: 6px 16px;
  background: var(--primary);
  color: var(--white);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 16px;
}

.hero-title {
  font-size: 42px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.03em;
  color: var(--charcoal);
  margin-bottom: 16px;
}

.hero-subtitle {
  font-size: 17px;
  color: var(--gray-600);
  line-height: 1.6;
  margin-bottom: 24px;
  max-width: 480px;
}

.hero-cta {
  display: inline-block;
  padding: 14px 32px;
  background: var(--primary);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 700;
  transition: background 0.2s, transform 0.15s;
  margin-right: 16px;
}

.hero-cta:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
}

.hero-badge {
  display: inline-block;
  padding: 8px 18px;
  background: var(--coral);
  color: var(--white);
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
  vertical-align: middle;
}

.hero-visual {
  display: flex;
  justify-content: center;
  align-items: center;
}

.hero-image-placeholder {
  position: relative;
  width: 100%;
  max-width: 400px;
  aspect-ratio: 1;
  border-radius: var(--radius-xl);
  background: linear-gradient(135deg, var(--primary-bg), #D4F0F2);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.hero-illustration {
  width: 80%;
  height: 80%;
}

.hero-challenge-badge {
  position: absolute;
  top: 20px;
  right: 20px;
  background: var(--coral);
  color: var(--white);
  padding: 8px 18px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 700;
  box-shadow: var(--shadow-md);
}

/* ===== Trending ===== */
.trending {
  padding: 56px 0;
}

.trending .section-title {
  margin-bottom: 28px;
}

.trending-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.trending-card {
  display: flex;
  flex-direction: column;
  padding: 24px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.15s;
  position: relative;
}

.trending-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.trending-tag {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 14px;
  width: fit-content;
}

.tag-heart { background: #FDE8E8; color: #C0392B; }
.tag-wellness { background: #E8F6F7; color: var(--primary); }
.tag-lifestyle { background: #FFF3E0; color: #E67E22; }
.tag-products { background: #F3E5F5; color: #8E44AD; }

.trending-card h3 {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--charcoal);
  flex: 1;
}

.trending-arrow {
  position: absolute;
  top: 24px;
  right: 20px;
  font-size: 18px;
  color: var(--gray-300);
  transition: color 0.2s, transform 0.2s;
}

.trending-card:hover .trending-arrow {
  color: var(--primary);
  transform: translateX(3px);
}

/* ===== Newsletter CTA ===== */
.newsletter-cta {
  padding: 64px 0;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: var(--white);
}

.newsletter-cta-inner {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 48px;
  align-items: center;
}

.newsletter-cta-content h2 {
  font-size: 32px;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
  line-height: 1.2;
}

.newsletter-cta-content p {
  font-size: 16px;
  opacity: 0.9;
  margin-bottom: 24px;
  max-width: 500px;
  line-height: 1.6;
}

.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 460px;
}

.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,0.15);
  color: var(--white);
  font-size: 15px;
  font-family: var(--font);
  outline: none;
  transition: border-color 0.2s, background 0.2s;
}

.newsletter-form input::placeholder {
  color: rgba(255,255,255,0.6);
}

.newsletter-form input:focus {
  border-color: var(--coral);
  background: rgba(255,255,255,0.2);
}

.btn-join {
  padding: 14px 28px;
  background: var(--coral);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 700;
  transition: background 0.2s, transform 0.15s;
  white-space: nowrap;
}

.btn-join:hover {
  background: var(--coral-dark);
  transform: translateY(-1px);
}

.newsletter-privacy {
  display: block;
  margin-top: 12px;
  font-size: 12px;
  opacity: 0.7;
}

.newsletter-cta-visual {
  width: 180px;
  height: 180px;
  opacity: 0.6;
}

/* ===== Health Topics Carousel ===== */
.health-topics {
  padding: 56px 0;
  background: var(--gray-50);
}

.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding: 8px 4px 16px;
  -ms-overflow-style: none;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: var(--shadow-lg);
  font-size: 24px;
  color: var(--charcoal);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: background 0.2s, color 0.2s, box-shadow 0.2s;
  border: 1px solid var(--gray-200);
}

.carousel-arrow:hover {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
  box-shadow: var(--shadow-xl);
}

.carousel-arrow-left { left: -12px; }
.carousel-arrow-right { right: -12px; }

.topic-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
  width: 160px;
  padding: 20px 16px;
  border-radius: var(--radius-md);
  background: var(--white);
  transition: transform 0.2s, box-shadow 0.2s;
}

.topic-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.topic-img {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.topic-img svg {
  width: 60%;
  height: 60%;
}

.topic-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  text-align: center;
  line-height: 1.3;
}

/* ===== Health Tools ===== */
.tools {
  padding: 56px 0;
}

.tools .section-title {
  margin-bottom: 28px;
}

.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}

.tools-nutrition {
  background: var(--primary-bg);
  border-radius: var(--radius-lg);
  padding: 28px;
}

.nutrition-header h3 {
  font-size: 22px;
  font-weight: 800;
  color: var(--charcoal);
  margin-bottom: 8px;
}

.nutrition-header p {
  font-size: 14px;
  color: var(--gray-600);
  margin-bottom: 16px;
  line-height: 1.5;
  max-width: 400px;
}

.btn-outline {
  display: inline-block;
  padding: 10px 22px;
  border: 2px solid var(--primary);
  color: var(--primary);
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s, color 0.2s;
}

.btn-outline:hover {
  background: var(--primary);
  color: var(--white);
}

.nutrition-tools {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 20px;
}

.tool-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: var(--white);
  border-radius: var(--radius-md);
  transition: box-shadow 0.2s, transform 0.15s;
}

.tool-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateX(4px);
}

.tool-icon {
  font-size: 28px;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.tool-card h4 {
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 2px;
}

.tool-card p {
  font-size: 13px;
  color: var(--gray-500);
  line-height: 1.4;
}

.tools-care {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.care-card {
  display: flex;
  flex-direction: column;
  padding: 20px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.15s;
}

.care-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.care-card-main {
  grid-column: 1 / -1;
}

.care-icon {
  font-size: 28px;
  margin-bottom: 10px;
}

.care-card h4 {
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 6px;
}

.care-card p {
  font-size: 13px;
  color: var(--gray-500);
  line-height: 1.5;
}

.btn-link {
  display: inline-block;
  margin-top: 10px;
  font-size: 13px;
  font-weight: 600;
  color: var(--primary);
}

.btn-link:hover {
  color: var(--primary-dark);
}

/* ===== Recommended Reads ===== */
.recommended-reads {
  padding: 56px 0;
  background: var(--gray-50);
}

.reads-tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 28px;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 4px;
}

.reads-tabs::-webkit-scrollbar { display: none; }

.reads-tab {
  padding: 10px 22px;
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-600);
  border-radius: 24px;
  white-space: nowrap;
  transition: background 0.2s, color 0.2s;
  border: 1.5px solid var(--gray-200);
  background: var(--white);
}

.reads-tab:hover {
  color: var(--primary);
  border-color: var(--primary);
}

.reads-tab.active {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
}

.reads-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.reads-card {
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.reads-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.reads-card-img {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.reads-card-body {
  padding: 20px;
}

.reads-card-tag {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 10px;
}

.reads-card-body h3 {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--charcoal);
}

.reads-card-body .reads-meta {
  font-size: 12px;
  color: var(--gray-400);
  margin-top: 8px;
}

/* ===== Trust Section ===== */
.trust-section {
  padding: 64px 0;
}

.trust-section .section-title {
  text-align: center;
  margin-bottom: 40px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px;
}

.trust-card {
  text-align: center;
  padding: 32px 24px;
  border-radius: var(--radius-lg);
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.trust-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.trust-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 20px;
}

.trust-icon svg {
  width: 100%;
  height: 100%;
}

.trust-card h3 {
  font-size: 17px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 8px;
}

.trust-card p {
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== Featured Programs ===== */
.featured-programs {
  padding: 56px 0;
  background: var(--gray-50);
}

.programs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.program-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.program-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.program-img {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.program-img svg {
  width: 60%;
  height: 60%;
}

.program-card h4 {
  padding: 16px 20px;
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  line-height: 1.4;
}

/* ===== Latest Videos ===== */
.latest-videos {
  padding: 56px 0;
}

.videos-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.video-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.video-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.video-thumb {
  position: relative;
  aspect-ratio: 16/10;
  overflow: hidden;
}

.video-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.video-placeholder svg {
  width: 48px;
  height: 48px;
  opacity: 0.9;
  transition: transform 0.2s;
}

.video-card:hover .video-placeholder svg {
  transform: scale(1.1);
}

.video-card h4 {
  padding: 14px 16px;
  font-size: 14px;
  font-weight: 700;
  color: var(--charcoal);
  line-height: 1.4;
}

/* ===== Footer ===== */
.site-footer {
  background: var(--charcoal);
  color: var(--gray-300);
  padding: 56px 0 0;
}

.footer-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.footer-top {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 56px;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-newsletter h3 {
  font-size: 20px;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 12px;
}

.footer-newsletter p {
  font-size: 14px;
  line-height: 1.6;
  margin-bottom: 20px;
  max-width: 400px;
}

.footer-newsletter-form {
  display: flex;
  gap: 10px;
}

.footer-newsletter-form input {
  flex: 1;
  padding: 12px 16px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-sm);
  color: var(--white);
  font-size: 14px;
  font-family: var(--font);
  outline: none;
  transition: border-color 0.2s;
}

.footer-newsletter-form input::placeholder {
  color: rgba(255,255,255,0.4);
}

.footer-newsletter-form input:focus {
  border-color: var(--coral);
}

.btn-signup {
  padding: 12px 24px;
  background: var(--coral);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
  white-space: nowrap;
}

.btn-signup:hover {
  background: var(--coral-dark);
}

.footer-links-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 700;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-col a {
  font-size: 13px;
  color: var(--gray-400);
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--white);
}

.social-links a {
  display: inline-flex;
}

.footer-bottom {
  padding: 24px 0;
  margin-top: 0;
}

.footer-bottom p {
  font-size: 12px;
  color: var(--gray-500);
  line-height: 1.6;
  max-width: 900px;
}

/* ===== Newsletter Success State ===== */
.newsletter-form.success,
.footer-newsletter-form.success {
  position: relative;
}

.newsletter-form.success input,
.footer-newsletter-form.success input {
  opacity: 0.5;
  pointer-events: none;
}

.newsletter-form.success .btn-join,
.footer-newsletter-form.success .btn-signup {
  opacity: 0.5;
  pointer-events: none;
}

.success-message {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: var(--white);
  color: var(--primary);
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 14px;
  box-shadow: var(--shadow-lg);
  white-space: nowrap;
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .hero-title {
    font-size: 32px;
  }
  .hero-visual {
    display: none;
  }
  .trending-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .tools-grid {
    grid-template-columns: 1fr;
  }
  .trust-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .programs-grid,
  .videos-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-top {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .reads-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .main-nav {
    display: none;
    position: fixed;
    top: 64px;
    left: 0;
    right: 0;
    bottom: 0;
    background: var(--white);
    flex-direction: column;
    padding: 20px;
    overflow-y: auto;
    z-index: 90;
  }

  .main-nav.open {
    display: flex;
  }

  .nav-item {
    width: 100%;
  }

  .nav-link {
    width: 100%;
    justify-content: space-between;
    padding: 14px 16px;
    font-size: 16px;
    border-bottom: 1px solid var(--gray-100);
  }

  .mega-menu {
    position: static;
    transform: none;
    box-shadow: none;
    border: none;
    padding: 0 16px 16px;
    min-width: unset;
    border-radius: 0;
  }

  .nav-item.active .mega-menu {
    transform: none;
  }

  .mega-menu-inner {
    flex-direction: column;
    gap: 16px;
  }

  .mega-highlight {
    margin: 0;
  }

  .mobile-menu-toggle {
    display: flex;
  }

  .mobile-menu-toggle.active span:nth-child(1) {
    transform: rotate(45deg) translate(5px, 5px);
  }
  .mobile-menu-toggle.active span:nth-child(2) {
    opacity: 0;
  }
  .mobile-menu-toggle.active span:nth-child(3) {
    transform: rotate(-45deg) translate(5px, -5px);
  }

  .header-actions {
    display: none;
  }

  .trending-grid {
    grid-template-columns: 1fr;
  }

  .tools-care {
    grid-template-columns: 1fr;
  }

  .reads-grid {
    grid-template-columns: 1fr;
  }

  .trust-grid {
    grid-template-columns: 1fr;
  }

  .programs-grid,
  .videos-grid {
    grid-template-columns: 1fr;
  }

  .footer-links-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .hero-title {
    font-size: 28px;
  }

  .newsletter-cta-inner {
    grid-template-columns: 1fr;
  }

  .newsletter-cta-visual {
    display: none;
  }

  .section-title {
    font-size: 24px;
  }

  .newsletter-cta-content h2 {
    font-size: 24px;
  }
}

@media (max-width: 480px) {
  .newsletter-form {
    flex-direction: column;
  }

  .footer-newsletter-form {
    flex-direction: column;
  }

  .footer-links-grid {
    grid-template-columns: 1fr;
  }

  .hero-badge {
    display: block;
    margin-top: 12px;
  }
}

/* ===== Reset & Base ===== */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --primary: #02838D;
  --primary-light: #06A4B0;
  --primary-dark: #016A73;
  --primary-bg: #E8F6F7;
  --charcoal: #231F20;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --coral: #E8915A;
  --coral-dark: #D4763E;
  --green-light: #E8F5E9;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: var(--font);
  color: var(--charcoal);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
  transition: color 0.2s;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

ul { list-style: none; }

img { max-width: 100%; display: block; }

/* ===== Credibility Ticker ===== */
.credibility-ticker {
  background: var(--primary);
  color: var(--white);
  overflow: hidden;
  white-space: nowrap;
  padding: 10px 0;
  position: relative;
  z-index: 100;
}

.ticker-track {
  display: inline-flex;
  align-items: center;
  gap: 32px;
  animation: ticker-scroll 30s linear infinite;
}

.ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.ticker-icon {
  font-size: 16px;
  opacity: 0.9;
}

.ticker-divider {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(255,255,255,0.4);
  flex-shrink: 0;
}

@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ===== Header ===== */
.site-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  z-index: 90;
  box-shadow: var(--shadow-sm);
}

.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  height: 64px;
  gap: 32px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.logo-icon {
  font-size: 28px;
  color: var(--primary);
}

.logo-text {
  font-size: 22px;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: -0.02em;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.nav-item {
  position: relative;
}

.nav-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  border-radius: var(--radius-sm);
  transition: background 0.2s, color 0.2s;
}

.nav-link:hover {
  background: var(--gray-100);
  color: var(--primary);
}

.nav-arrow {
  font-size: 10px;
  transition: transform 0.2s;
}

.nav-item.active .nav-arrow {
  transform: rotate(180deg);
}

.nav-item.active .nav-link {
  background: var(--primary-bg);
  color: var(--primary);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--gray-200);
  padding: 24px 28px;
  min-width: 480px;
  opacity: 0;
  visibility: hidden;
  transform: translateX(-50%) translateY(8px);
  transition: opacity 0.2s, transform 0.2s, visibility 0.2s;
  z-index: 100;
}

.nav-item.active .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.mega-menu-inner {
  display: flex;
  gap: 32px;
}

.mega-col h4 {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--primary-bg);
}

.mega-col ul {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.mega-col a {
  font-size: 14px;
  color: var(--gray-700);
  padding: 6px 10px;
  border-radius: 6px;
  transition: background 0.15s, color 0.15s;
  display: block;
}

.mega-col a:hover {
  background: var(--primary-bg);
  color: var(--primary);
}

.mega-highlight {
  background: var(--primary-bg);
  padding: 16px 20px;
  border-radius: var(--radius-md);
  margin: -8px -12px;
  align-self: flex-start;
}

/* Header Actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.btn-subscribe {
  padding: 8px 20px;
  background: var(--primary);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}

.btn-subscribe:hover {
  background: var(--primary-dark);
}

.btn-signin {
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  color: var(--primary);
  border: 1.5px solid var(--primary);
  border-radius: var(--radius-sm);
  transition: background 0.2s, color 0.2s;
}

.btn-signin:hover {
  background: var(--primary);
  color: var(--white);
}

/* Mobile Menu Toggle */
.mobile-menu-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.mobile-menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--charcoal);
  border-radius: 2px;
  transition: transform 0.3s, opacity 0.3s;
}

/* ===== Section Common ===== */
.section-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.section-title {
  font-size: 28px;
  font-weight: 800;
  color: var(--charcoal);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28px;
}

.view-all {
  font-size: 14px;
  font-weight: 600;
  color: var(--primary);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: gap 0.2s;
}

.view-all:hover {
  gap: 8px;
}

.view-all::after {
  content: '\2192';
}

/* ===== Hero ===== */
.hero {
  background: linear-gradient(135deg, var(--primary-bg) 0%, #F0FBFC 50%, var(--white) 100%);
  padding: 48px 0;
}

.hero-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.hero-category {
  display: inline-block;
  padding: 6px 16px;
  background: var(--primary);
  color: var(--white);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 16px;
}

.hero-title {
  font-size: 42px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.03em;
  color: var(--charcoal);
  margin-bottom: 16px;
}

.hero-subtitle {
  font-size: 17px;
  color: var(--gray-600);
  line-height: 1.6;
  margin-bottom: 24px;
  max-width: 480px;
}

.hero-cta {
  display: inline-block;
  padding: 14px 32px;
  background: var(--primary);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 700;
  transition: background 0.2s, transform 0.15s;
  margin-right: 16px;
}

.hero-cta:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
}

.hero-badge {
  display: inline-block;
  padding: 8px 18px;
  background: var(--coral);
  color: var(--white);
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
  vertical-align: middle;
}

.hero-visual {
  display: flex;
  justify-content: center;
  align-items: center;
}

.hero-image-placeholder {
  position: relative;
  width: 100%;
  max-width: 400px;
  aspect-ratio: 1;
  border-radius: var(--radius-xl);
  background: linear-gradient(135deg, var(--primary-bg), #D4F0F2);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.hero-illustration {
  width: 80%;
  height: 80%;
}

.hero-challenge-badge {
  position: absolute;
  top: 20px;
  right: 20px;
  background: var(--coral);
  color: var(--white);
  padding: 8px 18px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 700;
  box-shadow: var(--shadow-md);
}

/* ===== Trending ===== */
.trending {
  padding: 56px 0;
}

.trending .section-title {
  margin-bottom: 28px;
}

.trending-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.trending-card {
  display: flex;
  flex-direction: column;
  padding: 24px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.15s;
  position: relative;
}

.trending-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.trending-tag {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 14px;
  width: fit-content;
}

.tag-heart { background: #FDE8E8; color: #C0392B; }
.tag-wellness { background: #E8F6F7; color: var(--primary); }
.tag-lifestyle { background: #FFF3E0; color: #E67E22; }
.tag-products { background: #F3E5F5; color: #8E44AD; }

.trending-card h3 {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--charcoal);
  flex: 1;
}

.trending-arrow {
  position: absolute;
  top: 24px;
  right: 20px;
  font-size: 18px;
  color: var(--gray-300);
  transition: color 0.2s, transform 0.2s;
}

.trending-card:hover .trending-arrow {
  color: var(--primary);
  transform: translateX(3px);
}

/* ===== Newsletter CTA ===== */
.newsletter-cta {
  padding: 64px 0;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: var(--white);
}

.newsletter-cta-inner {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 48px;
  align-items: center;
}

.newsletter-cta-content h2 {
  font-size: 32px;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
  line-height: 1.2;
}

.newsletter-cta-content p {
  font-size: 16px;
  opacity: 0.9;
  margin-bottom: 24px;
  max-width: 500px;
  line-height: 1.6;
}

.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 460px;
}

.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,0.15);
  color: var(--white);
  font-size: 15px;
  font-family: var(--font);
  outline: none;
  transition: border-color 0.2s, background 0.2s;
}

.newsletter-form input::placeholder {
  color: rgba(255,255,255,0.6);
}

.newsletter-form input:focus {
  border-color: var(--coral);
  background: rgba(255,255,255,0.2);
}

.btn-join {
  padding: 14px 28px;
  background: var(--coral);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 700;
  transition: background 0.2s, transform 0.15s;
  white-space: nowrap;
}

.btn-join:hover {
  background: var(--coral-dark);
  transform: translateY(-1px);
}

.newsletter-privacy {
  display: block;
  margin-top: 12px;
  font-size: 12px;
  opacity: 0.7;
}

.newsletter-cta-visual {
  width: 180px;
  height: 180px;
  opacity: 0.6;
}

/* ===== Health Topics Carousel ===== */
.health-topics {
  padding: 56px 0;
  background: var(--gray-50);
}

.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding: 8px 4px 16px;
  -ms-overflow-style: none;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: var(--shadow-lg);
  font-size: 24px;
  color: var(--charcoal);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: background 0.2s, color 0.2s, box-shadow 0.2s;
  border: 1px solid var(--gray-200);
}

.carousel-arrow:hover {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
  box-shadow: var(--shadow-xl);
}

.carousel-arrow-left { left: -12px; }
.carousel-arrow-right { right: -12px; }

.topic-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
  width: 160px;
  padding: 20px 16px;
  border-radius: var(--radius-md);
  background: var(--white);
  transition: transform 0.2s, box-shadow 0.2s;
}

.topic-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.topic-img {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.topic-img svg {
  width: 60%;
  height: 60%;
}

.topic-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  text-align: center;
  line-height: 1.3;
}

/* ===== Health Tools ===== */
.tools {
  padding: 56px 0;
}

.tools .section-title {
  margin-bottom: 28px;
}

.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}

.tools-nutrition {
  background: var(--primary-bg);
  border-radius: var(--radius-lg);
  padding: 28px;
}

.nutrition-header h3 {
  font-size: 22px;
  font-weight: 800;
  color: var(--charcoal);
  margin-bottom: 8px;
}

.nutrition-header p {
  font-size: 14px;
  color: var(--gray-600);
  margin-bottom: 16px;
  line-height: 1.5;
  max-width: 400px;
}

.btn-outline {
  display: inline-block;
  padding: 10px 22px;
  border: 2px solid var(--primary);
  color: var(--primary);
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s, color 0.2s;
}

.btn-outline:hover {
  background: var(--primary);
  color: var(--white);
}

.nutrition-tools {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 20px;
}

.tool-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: var(--white);
  border-radius: var(--radius-md);
  transition: box-shadow 0.2s, transform 0.15s;
}

.tool-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateX(4px);
}

.tool-icon {
  font-size: 28px;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.tool-card h4 {
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 2px;
}

.tool-card p {
  font-size: 13px;
  color: var(--gray-500);
  line-height: 1.4;
}

.tools-care {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.care-card {
  display: flex;
  flex-direction: column;
  padding: 20px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.15s;
}

.care-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.care-card-main {
  grid-column: 1 / -1;
}

.care-icon {
  font-size: 28px;
  margin-bottom: 10px;
}

.care-card h4 {
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 6px;
}

.care-card p {
  font-size: 13px;
  color: var(--gray-500);
  line-height: 1.5;
}

.btn-link {
  display: inline-block;
  margin-top: 10px;
  font-size: 13px;
  font-weight: 600;
  color: var(--primary);
}

.btn-link:hover {
  color: var(--primary-dark);
}

/* ===== Recommended Reads ===== */
.recommended-reads {
  padding: 56px 0;
  background: var(--gray-50);
}

.reads-tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 28px;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 4px;
}

.reads-tabs::-webkit-scrollbar { display: none; }

.reads-tab {
  padding: 10px 22px;
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-600);
  border-radius: 24px;
  white-space: nowrap;
  transition: background 0.2s, color 0.2s;
  border: 1.5px solid var(--gray-200);
  background: var(--white);
}

.reads-tab:hover {
  color: var(--primary);
  border-color: var(--primary);
}

.reads-tab.active {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
}

.reads-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.reads-card {
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.reads-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.reads-card-img {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.reads-card-body {
  padding: 20px;
}

.reads-card-tag {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 10px;
}

.reads-card-body h3 {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--charcoal);
}

.reads-card-body .reads-meta {
  font-size: 12px;
  color: var(--gray-400);
  margin-top: 8px;
}

/* ===== Trust Section ===== */
.trust-section {
  padding: 64px 0;
}

.trust-section .section-title {
  text-align: center;
  margin-bottom: 40px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px;
}

.trust-card {
  text-align: center;
  padding: 32px 24px;
  border-radius: var(--radius-lg);
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.trust-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.trust-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 20px;
}

.trust-icon svg {
  width: 100%;
  height: 100%;
}

.trust-card h3 {
  font-size: 17px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 8px;
}

.trust-card p {
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== Featured Programs ===== */
.featured-programs {
  padding: 56px 0;
  background: var(--gray-50);
}

.programs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.program-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.program-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.program-img {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.program-img svg {
  width: 60%;
  height: 60%;
}

.program-card h4 {
  padding: 16px 20px;
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  line-height: 1.4;
}

/* ===== Latest Videos ===== */
.latest-videos {
  padding: 56px 0;
}

.videos-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.video-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.video-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.video-thumb {
  position: relative;
  aspect-ratio: 16/10;
  overflow: hidden;
}

.video-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.video-placeholder svg {
  width: 48px;
  height: 48px;
  opacity: 0.9;
  transition: transform 0.2s;
}

.video-card:hover .video-placeholder svg {
  transform: scale(1.1);
}

.video-card h4 {
  padding: 14px 16px;
  font-size: 14px;
  font-weight: 700;
  color: var(--charcoal);
  line-height: 1.4;
}

/* ===== Footer ===== */
.site-footer {
  background: var(--charcoal);
  color: var(--gray-300);
  padding: 56px 0 0;
}

.footer-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.footer-top {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 56px;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-newsletter h3 {
  font-size: 20px;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 12px;
}

.footer-newsletter p {
  font-size: 14px;
  line-height: 1.6;
  margin-bottom: 20px;
  max-width: 400px;
}

.footer-newsletter-form {
  display: flex;
  gap: 10px;
}

.footer-newsletter-form input {
  flex: 1;
  padding: 12px 16px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-sm);
  color: var(--white);
  font-size: 14px;
  font-family: var(--font);
  outline: none;
  transition: border-color 0.2s;
}

.footer-newsletter-form input::placeholder {
  color: rgba(255,255,255,0.4);
}

.footer-newsletter-form input:focus {
  border-color: var(--coral);
}

.btn-signup {
  padding: 12px 24px;
  background: var(--coral);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
  white-space: nowrap;
}

.btn-signup:hover {
  background: var(--coral-dark);
}

.footer-links-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 700;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-col a {
  font-size: 13px;
  color: var(--gray-400);
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--white);
}

.social-links a {
  display: inline-flex;
}

.footer-bottom {
  padding: 24px 0;
  margin-top: 0;
}

.footer-bottom p {
  font-size: 12px;
  color: var(--gray-500);
  line-height: 1.6;
  max-width: 900px;
}

/* ===== Newsletter Success State ===== */
.newsletter-form.success,
.footer-newsletter-form.success {
  position: relative;
}

.newsletter-form.success input,
.footer-newsletter-form.success input {
  opacity: 0.5;
  pointer-events: none;
}

.newsletter-form.success .btn-join,
.footer-newsletter-form.success .btn-signup {
  opacity: 0.5;
  pointer-events: none;
}

.success-message {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: var(--white);
  color: var(--primary);
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 14px;
  box-shadow: var(--shadow-lg);
  white-space: nowrap;
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .hero-title {
    font-size: 32px;
  }
  .hero-visual {
    display: none;
  }
  .trending-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .tools-grid {
    grid-template-columns: 1fr;
  }
  .trust-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .programs-grid,
  .videos-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-top {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .reads-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .main-nav {
    display: none;
    position: fixed;
    top: 64px;
    left: 0;
    right: 0;
    bottom: 0;
    background: var(--white);
    flex-direction: column;
    padding: 20px;
    overflow-y: auto;
    z-index: 90;
  }

  .main-nav.open {
    display: flex;
  }

  .nav-item {
    width: 100%;
  }

  .nav-link {
    width: 100%;
    justify-content: space-between;
    padding: 14px 16px;
    font-size: 16px;
    border-bottom: 1px solid var(--gray-100);
  }

  .mega-menu {
    position: static;
    transform: none;
    box-shadow: none;
    border: none;
    padding: 0 16px 16px;
    min-width: unset;
    border-radius: 0;
  }

  .nav-item.active .mega-menu {
    transform: none;
  }

  .mega-menu-inner {
    flex-direction: column;
    gap: 16px;
  }

  .mega-highlight {
    margin: 0;
  }

  .mobile-menu-toggle {
    display: flex;
  }

  .mobile-menu-toggle.active span:nth-child(1) {
    transform: rotate(45deg) translate(5px, 5px);
  }
  .mobile-menu-toggle.active span:nth-child(2) {
    opacity: 0;
  }
  .mobile-menu-toggle.active span:nth-child(3) {
    transform: rotate(-45deg) translate(5px, -5px);
  }

  .header-actions {
    display: none;
  }

  .trending-grid {
    grid-template-columns: 1fr;
  }

  .tools-care {
    grid-template-columns: 1fr;
  }

  .reads-grid {
    grid-template-columns: 1fr;
  }

  .trust-grid {
    grid-template-columns: 1fr;
  }

  .programs-grid,
  .videos-grid {
    grid-template-columns: 1fr;
  }

  .footer-links-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .hero-title {
    font-size: 28px;
  }

  .newsletter-cta-inner {
    grid-template-columns: 1fr;
  }

  .newsletter-cta-visual {
    display: none;
  }

  .section-title {
    font-size: 24px;
  }

  .newsletter-cta-content h2 {
    font-size: 24px;
  }
}

@media (max-width: 480px) {
  .newsletter-form {
    flex-direction: column;
  }

  .footer-newsletter-form {
    flex-direction: column;
  }

  .footer-links-grid {
    grid-template-columns: 1fr;
  }

  .hero-badge {
    display: block;
    margin-top: 12px;
  }
}

raw_arguments.content:
/* ===== Reset & Base ===== */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --primary: #02838D;
  --primary-light: #06A4B0;
  --primary-dark: #016A73;
  --primary-bg: #E8F6F7;
  --charcoal: #231F20;
  --white: #FFFFFF;
  --gray-50: #F9FAFB;
  --gray-100: #F3F4F6;
  --gray-200: #E5E7EB;
  --gray-300: #D1D5DB;
  --gray-400: #9CA3AF;
  --gray-500: #6B7280;
  --gray-600: #4B5563;
  --gray-700: #374151;
  --coral: #E8915A;
  --coral-dark: #D4763E;
  --green-light: #E8F5E9;
  --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 20px;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
}

body {
  font-family: var(--font);
  color: var(--charcoal);
  background: var(--white);
  line-height: 1.6;
  overflow-x: hidden;
}

a {
  text-decoration: none;
  color: inherit;
  transition: color 0.2s;
}

button {
  cursor: pointer;
  border: none;
  background: none;
  font-family: inherit;
}

ul { list-style: none; }

img { max-width: 100%; display: block; }

/* ===== Credibility Ticker ===== */
.credibility-ticker {
  background: var(--primary);
  color: var(--white);
  overflow: hidden;
  white-space: nowrap;
  padding: 10px 0;
  position: relative;
  z-index: 100;
}

.ticker-track {
  display: inline-flex;
  align-items: center;
  gap: 32px;
  animation: ticker-scroll 30s linear infinite;
}

.ticker-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.ticker-icon {
  font-size: 16px;
  opacity: 0.9;
}

.ticker-divider {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: rgba(255,255,255,0.4);
  flex-shrink: 0;
}

@keyframes ticker-scroll {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ===== Header ===== */
.site-header {
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  position: sticky;
  top: 0;
  z-index: 90;
  box-shadow: var(--shadow-sm);
}

.header-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  display: flex;
  align-items: center;
  height: 64px;
  gap: 32px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-shrink: 0;
}

.logo-icon {
  font-size: 28px;
  color: var(--primary);
}

.logo-text {
  font-size: 22px;
  font-weight: 800;
  color: var(--primary);
  letter-spacing: -0.02em;
}

.main-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
}

.nav-item {
  position: relative;
}

.nav-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 8px 14px;
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  border-radius: var(--radius-sm);
  transition: background 0.2s, color 0.2s;
}

.nav-link:hover {
  background: var(--gray-100);
  color: var(--primary);
}

.nav-arrow {
  font-size: 10px;
  transition: transform 0.2s;
}

.nav-item.active .nav-arrow {
  transform: rotate(180deg);
}

.nav-item.active .nav-link {
  background: var(--primary-bg);
  color: var(--primary);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  background: var(--white);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-xl);
  border: 1px solid var(--gray-200);
  padding: 24px 28px;
  min-width: 480px;
  opacity: 0;
  visibility: hidden;
  transform: translateX(-50%) translateY(8px);
  transition: opacity 0.2s, transform 0.2s, visibility 0.2s;
  z-index: 100;
}

.nav-item.active .mega-menu {
  opacity: 1;
  visibility: visible;
  transform: translateX(-50%) translateY(0);
}

.mega-menu-inner {
  display: flex;
  gap: 32px;
}

.mega-col h4 {
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--primary);
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 2px solid var(--primary-bg);
}

.mega-col ul {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.mega-col a {
  font-size: 14px;
  color: var(--gray-700);
  padding: 6px 10px;
  border-radius: 6px;
  transition: background 0.15s, color 0.15s;
  display: block;
}

.mega-col a:hover {
  background: var(--primary-bg);
  color: var(--primary);
}

.mega-highlight {
  background: var(--primary-bg);
  padding: 16px 20px;
  border-radius: var(--radius-md);
  margin: -8px -12px;
  align-self: flex-start;
}

/* Header Actions */
.header-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
}

.btn-subscribe {
  padding: 8px 20px;
  background: var(--primary);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
}

.btn-subscribe:hover {
  background: var(--primary-dark);
}

.btn-signin {
  padding: 8px 16px;
  font-size: 14px;
  font-weight: 600;
  color: var(--primary);
  border: 1.5px solid var(--primary);
  border-radius: var(--radius-sm);
  transition: background 0.2s, color 0.2s;
}

.btn-signin:hover {
  background: var(--primary);
  color: var(--white);
}

/* Mobile Menu Toggle */
.mobile-menu-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
}

.mobile-menu-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--charcoal);
  border-radius: 2px;
  transition: transform 0.3s, opacity 0.3s;
}

/* ===== Section Common ===== */
.section-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.section-title {
  font-size: 28px;
  font-weight: 800;
  color: var(--charcoal);
  letter-spacing: -0.02em;
  line-height: 1.2;
}

.section-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 28px;
}

.view-all {
  font-size: 14px;
  font-weight: 600;
  color: var(--primary);
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: gap 0.2s;
}

.view-all:hover {
  gap: 8px;
}

.view-all::after {
  content: '\2192';
}

/* ===== Hero ===== */
.hero {
  background: linear-gradient(135deg, var(--primary-bg) 0%, #F0FBFC 50%, var(--white) 100%);
  padding: 48px 0;
}

.hero-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.hero-category {
  display: inline-block;
  padding: 6px 16px;
  background: var(--primary);
  color: var(--white);
  border-radius: 20px;
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 16px;
}

.hero-title {
  font-size: 42px;
  font-weight: 800;
  line-height: 1.15;
  letter-spacing: -0.03em;
  color: var(--charcoal);
  margin-bottom: 16px;
}

.hero-subtitle {
  font-size: 17px;
  color: var(--gray-600);
  line-height: 1.6;
  margin-bottom: 24px;
  max-width: 480px;
}

.hero-cta {
  display: inline-block;
  padding: 14px 32px;
  background: var(--primary);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 700;
  transition: background 0.2s, transform 0.15s;
  margin-right: 16px;
}

.hero-cta:hover {
  background: var(--primary-dark);
  transform: translateY(-1px);
}

.hero-badge {
  display: inline-block;
  padding: 8px 18px;
  background: var(--coral);
  color: var(--white);
  border-radius: 20px;
  font-size: 13px;
  font-weight: 600;
  vertical-align: middle;
}

.hero-visual {
  display: flex;
  justify-content: center;
  align-items: center;
}

.hero-image-placeholder {
  position: relative;
  width: 100%;
  max-width: 400px;
  aspect-ratio: 1;
  border-radius: var(--radius-xl);
  background: linear-gradient(135deg, var(--primary-bg), #D4F0F2);
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.hero-illustration {
  width: 80%;
  height: 80%;
}

.hero-challenge-badge {
  position: absolute;
  top: 20px;
  right: 20px;
  background: var(--coral);
  color: var(--white);
  padding: 8px 18px;
  border-radius: 20px;
  font-size: 14px;
  font-weight: 700;
  box-shadow: var(--shadow-md);
}

/* ===== Trending ===== */
.trending {
  padding: 56px 0;
}

.trending .section-title {
  margin-bottom: 28px;
}

.trending-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.trending-card {
  display: flex;
  flex-direction: column;
  padding: 24px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.15s;
  position: relative;
}

.trending-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

.trending-tag {
  display: inline-block;
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 14px;
  width: fit-content;
}

.tag-heart { background: #FDE8E8; color: #C0392B; }
.tag-wellness { background: #E8F6F7; color: var(--primary); }
.tag-lifestyle { background: #FFF3E0; color: #E67E22; }
.tag-products { background: #F3E5F5; color: #8E44AD; }

.trending-card h3 {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--charcoal);
  flex: 1;
}

.trending-arrow {
  position: absolute;
  top: 24px;
  right: 20px;
  font-size: 18px;
  color: var(--gray-300);
  transition: color 0.2s, transform 0.2s;
}

.trending-card:hover .trending-arrow {
  color: var(--primary);
  transform: translateX(3px);
}

/* ===== Newsletter CTA ===== */
.newsletter-cta {
  padding: 64px 0;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  color: var(--white);
}

.newsletter-cta-inner {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 48px;
  align-items: center;
}

.newsletter-cta-content h2 {
  font-size: 32px;
  font-weight: 800;
  letter-spacing: -0.02em;
  margin-bottom: 12px;
  line-height: 1.2;
}

.newsletter-cta-content p {
  font-size: 16px;
  opacity: 0.9;
  margin-bottom: 24px;
  max-width: 500px;
  line-height: 1.6;
}

.newsletter-form {
  display: flex;
  gap: 12px;
  max-width: 460px;
}

.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  border: 2px solid rgba(255,255,255,0.3);
  border-radius: var(--radius-sm);
  background: rgba(255,255,255,0.15);
  color: var(--white);
  font-size: 15px;
  font-family: var(--font);
  outline: none;
  transition: border-color 0.2s, background 0.2s;
}

.newsletter-form input::placeholder {
  color: rgba(255,255,255,0.6);
}

.newsletter-form input:focus {
  border-color: var(--coral);
  background: rgba(255,255,255,0.2);
}

.btn-join {
  padding: 14px 28px;
  background: var(--coral);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 15px;
  font-weight: 700;
  transition: background 0.2s, transform 0.15s;
  white-space: nowrap;
}

.btn-join:hover {
  background: var(--coral-dark);
  transform: translateY(-1px);
}

.newsletter-privacy {
  display: block;
  margin-top: 12px;
  font-size: 12px;
  opacity: 0.7;
}

.newsletter-cta-visual {
  width: 180px;
  height: 180px;
  opacity: 0.6;
}

/* ===== Health Topics Carousel ===== */
.health-topics {
  padding: 56px 0;
  background: var(--gray-50);
}

.carousel-wrapper {
  position: relative;
}

.carousel-track {
  display: flex;
  gap: 24px;
  overflow-x: auto;
  scroll-behavior: smooth;
  scrollbar-width: none;
  padding: 8px 4px 16px;
  -ms-overflow-style: none;
}

.carousel-track::-webkit-scrollbar {
  display: none;
}

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--white);
  box-shadow: var(--shadow-lg);
  font-size: 24px;
  color: var(--charcoal);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: background 0.2s, color 0.2s, box-shadow 0.2s;
  border: 1px solid var(--gray-200);
}

.carousel-arrow:hover {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
  box-shadow: var(--shadow-xl);
}

.carousel-arrow-left { left: -12px; }
.carousel-arrow-right { right: -12px; }

.topic-card {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  flex-shrink: 0;
  width: 160px;
  padding: 20px 16px;
  border-radius: var(--radius-md);
  background: var(--white);
  transition: transform 0.2s, box-shadow 0.2s;
}

.topic-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.topic-img {
  width: 100px;
  height: 100px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}

.topic-img svg {
  width: 60%;
  height: 60%;
}

.topic-label {
  font-size: 14px;
  font-weight: 600;
  color: var(--charcoal);
  text-align: center;
  line-height: 1.3;
}

/* ===== Health Tools ===== */
.tools {
  padding: 56px 0;
}

.tools .section-title {
  margin-bottom: 28px;
}

.tools-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 28px;
}

.tools-nutrition {
  background: var(--primary-bg);
  border-radius: var(--radius-lg);
  padding: 28px;
}

.nutrition-header h3 {
  font-size: 22px;
  font-weight: 800;
  color: var(--charcoal);
  margin-bottom: 8px;
}

.nutrition-header p {
  font-size: 14px;
  color: var(--gray-600);
  margin-bottom: 16px;
  line-height: 1.5;
  max-width: 400px;
}

.btn-outline {
  display: inline-block;
  padding: 10px 22px;
  border: 2px solid var(--primary);
  color: var(--primary);
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s, color 0.2s;
}

.btn-outline:hover {
  background: var(--primary);
  color: var(--white);
}

.nutrition-tools {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-top: 20px;
}

.tool-card {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 16px;
  background: var(--white);
  border-radius: var(--radius-md);
  transition: box-shadow 0.2s, transform 0.15s;
}

.tool-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateX(4px);
}

.tool-icon {
  font-size: 28px;
  width: 48px;
  height: 48px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.tool-card h4 {
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 2px;
}

.tool-card p {
  font-size: 13px;
  color: var(--gray-500);
  line-height: 1.4;
}

.tools-care {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.care-card {
  display: flex;
  flex-direction: column;
  padding: 20px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.15s;
}

.care-card:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.care-card-main {
  grid-column: 1 / -1;
}

.care-icon {
  font-size: 28px;
  margin-bottom: 10px;
}

.care-card h4 {
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 6px;
}

.care-card p {
  font-size: 13px;
  color: var(--gray-500);
  line-height: 1.5;
}

.btn-link {
  display: inline-block;
  margin-top: 10px;
  font-size: 13px;
  font-weight: 600;
  color: var(--primary);
}

.btn-link:hover {
  color: var(--primary-dark);
}

/* ===== Recommended Reads ===== */
.recommended-reads {
  padding: 56px 0;
  background: var(--gray-50);
}

.reads-tabs {
  display: flex;
  gap: 4px;
  margin-bottom: 28px;
  overflow-x: auto;
  scrollbar-width: none;
  -ms-overflow-style: none;
  padding-bottom: 4px;
}

.reads-tabs::-webkit-scrollbar { display: none; }

.reads-tab {
  padding: 10px 22px;
  font-size: 14px;
  font-weight: 600;
  color: var(--gray-600);
  border-radius: 24px;
  white-space: nowrap;
  transition: background 0.2s, color 0.2s;
  border: 1.5px solid var(--gray-200);
  background: var(--white);
}

.reads-tab:hover {
  color: var(--primary);
  border-color: var(--primary);
}

.reads-tab.active {
  background: var(--primary);
  color: var(--white);
  border-color: var(--primary);
}

.reads-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.reads-card {
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.reads-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.reads-card-img {
  height: 180px;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.reads-card-body {
  padding: 20px;
}

.reads-card-tag {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: 10px;
}

.reads-card-body h3 {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  color: var(--charcoal);
}

.reads-card-body .reads-meta {
  font-size: 12px;
  color: var(--gray-400);
  margin-top: 8px;
}

/* ===== Trust Section ===== */
.trust-section {
  padding: 64px 0;
}

.trust-section .section-title {
  text-align: center;
  margin-bottom: 40px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.trust-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 28px;
}

.trust-card {
  text-align: center;
  padding: 32px 24px;
  border-radius: var(--radius-lg);
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.trust-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.trust-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 20px;
}

.trust-icon svg {
  width: 100%;
  height: 100%;
}

.trust-card h3 {
  font-size: 17px;
  font-weight: 700;
  color: var(--charcoal);
  margin-bottom: 8px;
}

.trust-card p {
  font-size: 14px;
  color: var(--gray-500);
  line-height: 1.6;
}

/* ===== Featured Programs ===== */
.featured-programs {
  padding: 56px 0;
  background: var(--gray-50);
}

.programs-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.program-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.program-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.program-img {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.program-img svg {
  width: 60%;
  height: 60%;
}

.program-card h4 {
  padding: 16px 20px;
  font-size: 15px;
  font-weight: 700;
  color: var(--charcoal);
  line-height: 1.4;
}

/* ===== Latest Videos ===== */
.latest-videos {
  padding: 56px 0;
}

.videos-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}

.video-card {
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--white);
  border: 1px solid var(--gray-200);
  transition: box-shadow 0.2s, transform 0.15s;
}

.video-card:hover {
  box-shadow: var(--shadow-lg);
  transform: translateY(-3px);
}

.video-thumb {
  position: relative;
  aspect-ratio: 16/10;
  overflow: hidden;
}

.video-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}

.video-placeholder svg {
  width: 48px;
  height: 48px;
  opacity: 0.9;
  transition: transform 0.2s;
}

.video-card:hover .video-placeholder svg {
  transform: scale(1.1);
}

.video-card h4 {
  padding: 14px 16px;
  font-size: 14px;
  font-weight: 700;
  color: var(--charcoal);
  line-height: 1.4;
}

/* ===== Footer ===== */
.site-footer {
  background: var(--charcoal);
  color: var(--gray-300);
  padding: 56px 0 0;
}

.footer-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px;
}

.footer-top {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 56px;
  padding-bottom: 40px;
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.footer-newsletter h3 {
  font-size: 20px;
  font-weight: 700;
  color: var(--white);
  margin-bottom: 12px;
}

.footer-newsletter p {
  font-size: 14px;
  line-height: 1.6;
  margin-bottom: 20px;
  max-width: 400px;
}

.footer-newsletter-form {
  display: flex;
  gap: 10px;
}

.footer-newsletter-form input {
  flex: 1;
  padding: 12px 16px;
  background: rgba(255,255,255,0.1);
  border: 1px solid rgba(255,255,255,0.2);
  border-radius: var(--radius-sm);
  color: var(--white);
  font-size: 14px;
  font-family: var(--font);
  outline: none;
  transition: border-color 0.2s;
}

.footer-newsletter-form input::placeholder {
  color: rgba(255,255,255,0.4);
}

.footer-newsletter-form input:focus {
  border-color: var(--coral);
}

.btn-signup {
  padding: 12px 24px;
  background: var(--coral);
  color: var(--white);
  border-radius: var(--radius-sm);
  font-size: 14px;
  font-weight: 600;
  transition: background 0.2s;
  white-space: nowrap;
}

.btn-signup:hover {
  background: var(--coral-dark);
}

.footer-links-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.footer-col h4 {
  font-size: 13px;
  font-weight: 700;
  color: var(--white);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 16px;
}

.footer-col ul {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.footer-col a {
  font-size: 13px;
  color: var(--gray-400);
  transition: color 0.2s;
}

.footer-col a:hover {
  color: var(--white);
}

.social-links a {
  display: inline-flex;
}

.footer-bottom {
  padding: 24px 0;
  margin-top: 0;
}

.footer-bottom p {
  font-size: 12px;
  color: var(--gray-500);
  line-height: 1.6;
  max-width: 900px;
}

/* ===== Newsletter Success State ===== */
.newsletter-form.success,
.footer-newsletter-form.success {
  position: relative;
}

.newsletter-form.success input,
.footer-newsletter-form.success input {
  opacity: 0.5;
  pointer-events: none;
}

.newsletter-form.success .btn-join,
.footer-newsletter-form.success .btn-signup {
  opacity: 0.5;
  pointer-events: none;
}

.success-message {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  background: var(--white);
  color: var(--primary);
  padding: 12px 24px;
  border-radius: var(--radius-sm);
  font-weight: 600;
  font-size: 14px;
  box-shadow: var(--shadow-lg);
  white-space: nowrap;
}

/* ===== Responsive ===== */
@media (max-width: 1024px) {
  .hero-inner {
    grid-template-columns: 1fr;
    gap: 32px;
  }
  .hero-title {
    font-size: 32px;
  }
  .hero-visual {
    display: none;
  }
  .trending-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .tools-grid {
    grid-template-columns: 1fr;
  }
  .trust-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .programs-grid,
  .videos-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-top {
    grid-template-columns: 1fr;
    gap: 40px;
  }
  .reads-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 768px) {
  .main-nav {
    display: none;
    position: fixed;
    top: 64px;
    left: 0;
    right: 0;
    bottom: 0;
    background: var(--white);
    flex-direction: column;
    padding: 20px;
    overflow-y: auto;
    z-index: 90;
  }

  .main-nav.open {
    display: flex;
  }

  .nav-item {
    width: 100%;
  }

  .nav-link {
    width: 100%;
    justify-content: space-between;
    padding: 14px 16px;
    font-size: 16px;
    border-bottom: 1px solid var(--gray-100);
  }

  .mega-menu {
    position: static;
    transform: none;
    box-shadow: none;
    border: none;
    padding: 0 16px 16px;
    min-width: unset;
    border-radius: 0;
  }

  .nav-item.active .mega-menu {
    transform: none;
  }

  .mega-menu-inner {
    flex-direction: column;
    gap: 16px;
  }

  .mega-highlight {
    margin: 0;
  }

  .mobile-menu-toggle {
    display: flex;
  }

  .mobile-menu-toggle.active span:nth-child(1) {
    transform: rotate(45deg) translate(5px, 5px);
  }
  .mobile-menu-toggle.active span:nth-child(2) {
    opacity: 0;
  }
  .mobile-menu-toggle.active span:nth-child(3) {
    transform: rotate(-45deg) translate(5px, -5px);
  }

  .header-actions {
    display: none;
  }

  .trending-grid {
    grid-template-columns: 1fr;
  }

  .tools-care {
    grid-template-columns: 1fr;
  }

  .reads-grid {
    grid-template-columns: 1fr;
  }

  .trust-grid {
    grid-template-columns: 1fr;
  }

  .programs-grid,
  .videos-grid {
    grid-template-columns: 1fr;
  }

  .footer-links-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .hero-title {
    font-size: 28px;
  }

  .newsletter-cta-inner {
    grid-template-columns: 1fr;
  }

  .newsletter-cta-visual {
    display: none;
  }

  .section-title {
    font-size: 24px;
  }

  .newsletter-cta-content h2 {
    font-size: 24px;
  }
}

@media (max-width: 480px) {
  .newsletter-form {
    flex-direction: column;
  }

  .footer-newsletter-form {
    flex-direction: column;
  }

  .footer-links-grid {
    grid-template-columns: 1fr;
  }

  .hero-badge {
    display: block;
    margin-top: 12px;
  }
}

arguments.content:
document.addEventListener('DOMContentLoaded', () => {

  // ===== Mega Menu Dropdowns =====
  const navItems = document.querySelectorAll('.nav-item[data-dropdown]');
  let activeDropdown = null;

  navItems.forEach(item => {
    const btn = item.querySelector('.nav-link');

    btn.addEventListener('click', (e) => {
      e.stopPropagation();
      if (activeDropdown === item) {
        closeDropdowns();
      } else {
        closeDropdowns();
        item.classList.add('active');
        activeDropdown = item;
